import{z as n,x as r,o as t,c as d,q as A,j as i,D as E,d as e,s as l,S as o,b as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"扩散蒸馏与少步","description":"","frontmatter":{"title":"扩散蒸馏与少步","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/diffusion-distillation.md","filePath":"llm/diffusion-distillation.md","lastUpdated":1791413859000}'),p={name:"llm/diffusion-distillation.md"};function D(F,a,m,C,f,_){const B=r("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="扩散蒸馏与少步" tabindex="-1">扩散蒸馏与少步 <a class="header-anchor" href="#扩散蒸馏与少步" aria-label="Permalink to &quot;扩散蒸馏与少步&quot;">​</a></h1><div class="epigraph"><p>多步采样买的是沿向量场慢慢走。蒸馏把多步教师压成少步学生，用质量换延迟。</p><footer>—— Salimans, Ho, Progressive Distillation；Song 等 Consistency Models</footer></div><p><a href="/llm/transfusion">上一课</a>仍可能对图像槽走完整扩散链。<a href="/llm/ddpm">DDPM</a> 的 \\(T\\) 是税。缺口是少步：推理要 1–8 步而不是 50–1000。后课视频默认：每帧再乘时间，少步从可选变成必要。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐步去噪或 ODE 积分在每步调用同一骨干。交互式文生图、统一模型里的「边说边画」负担不起。少步有三条主要路线，约束各不相同，选型即选约束。</p><p>渐进蒸馏沿轨迹做减半。学生从教师初始化，学会用一步复现教师相邻两步的结果：对同一 \\(x_t\\)，教师连走两个半步到 \\(x_{t-2}\\)，学生在 \\(v\\)-参数化下回归这个终点（\\(v\\)-参数化在两端噪声水平上都数值稳定）。每轮把学生日程步数减半，反复 \\(\\log_2\\) 轮，1024 步教师可压到 4 步。</p><p><span class="marginnote">减半快得超出直觉：\\(1024\\to512\\to256\\to128\\to64\\to32\\to16\\to8\\to4\\)，一共只 \\(\\log_2(1024/4)=8\\) 轮就到 4 步。这就是「渐进」二字的账——每代学生只需要学会「把两步并成一步」这件小事，难任务被拆成了八份。</span>为什么逐代减半而不是直接教一步：一步跨越的区间太大，教师的局部曲率信息一次性丢光，学生学不动；减半让每代的回归区间都落在教师尚准确的范围内。误差会逐代累积：每代只对齐日程上的离散点，中途轨迹偏差被下一代当真值继承，所以教师要够强、两代日程要对齐。</p><p>一致性模型换一条约束：学自映射 \\(f_\\theta(x_t,t)\\)，把同一条轨迹上任意 \\(t\\) 的点映到同一端点，即同一轨迹上 \\(f_\\theta(x_t,t)=f_\\theta(x_{t&#39;},t&#39;)\\)；损失比较相邻两段映射的差，目标侧用停梯度的 EMA 参数。轨迹端点条件（\\(t\\) 趋近 \\(0\\) 时映射退化为恒等）由参数化强制，否则自洽约束没有锚点、平凡满足。它不要求教师逐步对齐，一步即可出图，代价是训练对超参、日程与数据顺序更敏感。</p><p><span class="marginnote">「自映射」用坐车打比方：同一条轨道上，无论你从哪一站上车（\\(t\\) 取多少），一致性模型都要求你最终在同一终点站下车。损失函数就是抽相邻两站各坐一次、比较两次下车位置差多少；EMA 目标侧相当于用一份「慢半拍的参考答案」，防止自己抄自己越抄越偏。</span></p><p>分布匹配蒸馏不给配对目标，在分布层面拉近：教师得分网络冻结、给真实数据打分；另一个得分网络持续拟合学生样本的分布，更新生成器时视为常数。两者之差在学生样本处给出「往哪挪能涨教师似然」的方向，一步学生生成器按它回归，等价于最小化与教师分布的 KL。直观：学生不再抄轨迹，只被要求样本落进教师分布的高概率区；教师的 CFG 伪影与数据缺陷也经这个分布差传过来。</p><p>少步不是新的物理：是用额外训练把轨迹缩短。教师若本身贴不住条件，学生会把 CFG 伪影一起学会。</p><p><span class="marginnote">1 步生成接近 GAN 的延迟，也接近 GAN 的失败：模式崩、过饱和。少步模型要单独评，不能只报教师 FID。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先训好多步教师（可含 <a href="/llm/cfg-image">CFG</a>），再按选定蒸馏目标训学生：要延迟下限选一致性或分布匹配，要稳与可控选渐进蒸馏。推理固定步数与日程——渐进蒸馏的学生换日程即失效，因为每代的回归区间按原日程标定，日程是训练合同的一部分。验收：FID、条件遵守、文字，以及完整的步数–质量曲线：路线不同曲线形状不同，1 步与 8 步的表现不是一条平滑线的两端。不要用理解基准（VQA）代替生成少步评测。</p>',14)),(t(),i(o,null,{default:E(()=>[l(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20TCH%5B%22%E5%A4%9A%E6%AD%A5%E6%95%99%E5%B8%88%22%5D%20--%3E%20DST%5B%22%E8%92%B8%E9%A6%8F%22%5D%0A%20%20DST%20--%3E%20STU%5B%22%E5%B0%91%E6%AD%A5%E5%AD%A6%E7%94%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),(t(),i(o,null,{default:E(()=>[l(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E6%95%99%E5%B8%88%E8%BD%A8%E8%BF%B9%EF%BC%9A%E5%99%AA%E5%A3%B0%E5%88%B0%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20Q%7B%22%E5%AD%A6%E7%94%9F%E5%AD%A6%E4%BB%80%E4%B9%88%E7%BA%A6%E6%9D%9F%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%E6%B8%90%E8%BF%9B%E8%92%B8%E9%A6%8F%7C%20P%5B%22%E6%B2%BF%E8%BD%A8%E8%BF%B9%EF%BC%9A%E6%AF%8F%E4%BB%A3%E6%8A%8A%E4%B8%A4%E6%AD%A5%E5%B9%B6%E6%88%90%E4%B8%80%E6%AD%A5%22%5D%0A%20%20P%20--%3E%20P2%5B%22%E7%A8%B3%E3%80%81%E5%8F%AF%E6%8E%A7%EF%BC%8C%E8%AF%AF%E5%B7%AE%E9%80%90%E4%BB%A3%E7%B4%AF%E7%A7%AF%22%5D%0A%20%20Q%20--%3E%7C%E4%B8%80%E8%87%B4%E6%80%A7%E6%A8%A1%E5%9E%8B%7C%20C%5B%22%E8%BD%A8%E8%BF%B9%E8%87%AA%E6%B4%BD%EF%BC%9A%E4%BB%BB%E6%84%8F%20t%20%E6%98%A0%E5%88%B0%E5%90%8C%E4%B8%80%E7%AB%AF%E7%82%B9%22%5D%0A%20%20C%20--%3E%20C2%5B%22%E4%B8%80%E6%AD%A5%E5%87%BA%E5%9B%BE%EF%BC%8C%E8%AE%AD%E7%BB%83%E5%AF%B9%E8%B6%85%E5%8F%82%E6%95%8F%E6%84%9F%22%5D%0A%20%20Q%20--%3E%7C%E5%88%86%E5%B8%83%E5%8C%B9%E9%85%8D%7C%20M%5B%22%E8%BD%A8%E8%BF%B9%E6%97%A0%E5%85%B3%EF%BC%9A%E5%8F%AA%E6%8A%8A%E6%A0%B7%E6%9C%AC%E6%8E%A8%E8%BF%9B%E6%95%99%E5%B8%88%E5%88%86%E5%B8%83%22%5D%0A%20%20M%20--%3E%20M2%5B%22%E9%87%87%E6%A0%B7%E5%99%A8%E8%87%AA%E7%94%B1%EF%BC%8C%E5%85%A8%E7%9B%98%E7%BB%A7%E6%89%BF%E6%95%99%E5%B8%88%E7%BC%BA%E9%99%B7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<p>教师轨迹定义从噪声到数据的曲线。学生若只拟合端点，中间可走歪：两端正确、中途穿出数据流形，一步采样恰好把中途的偏差暴露在输出里——这是纯端点回归做不成一步生成的原因。一致性把「中间必须落在轨迹上」写成任意时刻的自洽约束，一步输出才立得住。渐进蒸馏保持逐步语义，每代步数减半，误差会累积，所以教师要够强、日程要对齐；分布匹配则放弃轨迹、只锁分布，换来对采样器细节的自由，也换来对教师分布缺陷的全盘继承。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>蒸馏不提高 VAE 重构上限，也不修复教师的条件失败。</p><p><span class="marginnote">为什么重要：蒸馏只压缩「从噪声到图像」的采样过程，而 VAE 决定「潜变量能表达的图像上限」。如果 VAE 本身糊掉了细字和纹理，学生再怎么训也还原不回来——就像复印机分辨率不够，复印得再快也不会更清楚。所以少步模型的模糊要先分清是步数问题还是编码器问题。</span>下一课把生成从单帧扩到时空，步数与记忆同时涨。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>少步靠蒸馏或一致性，不是改一句采样器配置。</li><li>渐进蒸馏逐代减半、一致性自洽于轨迹、分布匹配只对齐分布。</li><li>学生会继承教师的 CFG 与伪影。</li><li>必须单独报步数–质量，不能只抄教师 FID。</li><li>出处：Salimans &amp; Ho Progressive Distillation；Song 等 Consistency Models；Yin 等分布匹配蒸馏。</li></ul>',6))])}const u=n(p,[["render",D]]);export{c as __pageData,u as default};
